BASE_CSS:
:root{--ink:#1d2530;--ink-2:#4a5765;--muted:#8b97a4;--line:#e5e9ee;--bg:#f4f6f8;
--card:#fff;--brand:#1f5e58;--brand-2:#2c8078;--brand-3:#e6f2f0;--danger:#a8483f;
--radius:14px}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font-size:14px;line-height:1.6;
font-family:"Microsoft YaHei","PingFang SC",system-ui,-apple-system,"Segoe UI",sans-serif}
.wrap{max-width:1280px;margin:0 auto;padding:0 28px}
.top{background:linear-gradient(100deg,#123b38 0%,#1f5e58 55%,#2f7a70 100%);color:#fff}
.top .inner{display:flex;align-items:center;justify-content:space-between;height:72px;
max-width:1280px;margin:0 auto;padding:0 28px}
.brand{display:flex;align-items:center;gap:14px}
.logo{width:38px;height:38px;border-radius:11px;background:rgba(255,255,255,.13);
border:1px solid rgba(255,255,255,.25);display:grid;place-items:center;font-weight:700;
letter-spacing:1px;font-size:15px}
.brand h1{font-size:17px;margin:0;font-weight:600;letter-spacing:.5px}
.brand p{margin:0;font-size:11.5px;color:rgba(255,255,255,.66);letter-spacing:1.2px}
.nav{display:flex;gap:6px;background:rgba(255,255,255,.1);padding:5px;border-radius:11px}
.nav a{padding:7px 16px;border-radius:8px;font-size:13px;color:rgba(255,255,255,.75)}
.nav a.on{background:#fff;color:var(--brand);font-weight:600}
.who{display:flex;align-items:center;gap:9px;font-size:12.5px;color:rgba(255,255,255,.8)}
.who b{color:#fff;font-weight:600;font-size:13px}
.who .sno{font-weight:400;font-size:11px;opacity:.72;margin-left:2px}
.who .switch{background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.3);
color:#fff;border-radius:8px;padding:5px 11px;font-size:12px;cursor:pointer}
.who .switch:hover{background:rgba(255,255,255,.26)}
.gate{position:fixed;inset:0;background:rgba(18,59,56,.45);display:none;
place-items:center;z-index:999;padding:20px}
.gate.show{display:grid}
.gate .box{background:#fff;border-radius:16px;padding:30px 32px;width:min(430px,92vw);
box-shadow:0 18px 50px rgba(15,40,38,.3)}
.gate h2{margin:0 0 6px;font-size:19px}
.gate p{margin:0 0 18px;font-size:12.5px;color:var(--muted)}
.gate input{width:100%;padding:12px 14px;border:1px solid var(--line);border-radius:10px;
font:inherit;font-size:14px;outline:none}
.gate input+input{margin-top:10px}
.gate input:focus{border-color:var(--brand-2)}
.gate .btn{width:100%;margin-top:14px;padding:12px}
.gate .err{color:var(--danger);font-size:12px;margin-top:9px;min-height:17px}
.page{padding:22px 0 44px}
.grid{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(320px,.85fr);gap:20px}
.card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);
box-shadow:0 1px 2px rgba(20,30,40,.04)}
.chat{display:flex;flex-direction:column;height:calc(100vh - 156px);min-height:560px}
.chat-head{display:flex;align-items:center;justify-content:space-between;padding:15px 20px;
border-bottom:1px solid var(--line)}
.chat-head h2{margin:0;font-size:15px;font-weight:600}
.tag{font-size:11px;color:var(--brand);background:var(--brand-3);border-radius:20px;
padding:3px 10px;margin-left:8px}
.tag.off{color:#8a6a2f;background:#fbf1dc}
.stream{flex:1;overflow-y:auto;padding:20px;display:flex;flex-direction:column;gap:16px}
.msg{display:flex;gap:10px;max-width:88%}
.msg .av{width:30px;height:30px;border-radius:9px;flex:0 0 30px;display:grid;
place-items:center;font-size:12px;font-weight:700}
.msg.bot .av{background:var(--brand-3);color:var(--brand)}
.msg.me{align-self:flex-end;flex-direction:row-reverse}
.msg.me .av{background:#eef1f4;color:var(--ink-2)}
.bubble{background:#f7f9fa;border:1px solid var(--line);border-radius:12px;padding:12px 15px;
white-space:pre-wrap;font-size:13.5px}
.msg.me .bubble{background:var(--brand);color:#fff;border-color:var(--brand)}
.guide{margin-top:12px;border-top:1px dashed var(--line);padding-top:11px}
.guide h4{margin:0 0 8px;font-size:11.5px;letter-spacing:1px;color:var(--brand);
font-weight:600}
.qlist{counter-reset:q;margin:0;padding:0;list-style:none;display:flex;flex-direction:column;
gap:9px}
.qlist li{counter-increment:q;display:flex;gap:9px;font-size:13px;color:var(--ink-2)}
.qlist li.click{cursor:pointer;padding:5px 7px;margin:-5px -7px;border-radius:8px;
transition:background .15s}
.qlist li.click:hover{background:#f5ece9}
.quiz{margin-top:10px;padding:12px 14px;border:1px solid #ecdcd7;border-radius:12px;background:#fffaf8}
.qtitle{font-size:11px;letter-spacing:1.2px;color:#a05a5a;margin-bottom:6px}
.qtxt{font-size:13.5px;color:#3a2226;line-height:1.6}
.opts{margin-top:8px;display:flex;flex-direction:column;gap:6px}
.opt{cursor:pointer;border:1px solid #ecdcd7;border-radius:9px;padding:7px 10px;font-size:13px;
color:#4c393e;transition:.15s}
.opt:hover{border-color:#c98c86;background:#fdf2f0}
.opt b{margin-right:7px;color:#8c2a34}
.opt.right{background:#eaf5ec;border-color:#8bbd97}
.opt.wrong{background:#fbeceb;border-color:#d08b86}
.opt.locked{cursor:default}
.qres{margin-top:8px;font-size:12.5px;color:#7a5b5f;line-height:1.7}
.ansBtn{cursor:pointer;border:1px solid #c98c86;background:#fff;color:#8c2a34;
padding:5px 12px;border-radius:8px;font-size:12.5px}
.qlist li:before{content:counter(q);flex:0 0 19px;height:19px;border-radius:50%;
background:var(--brand-3);color:var(--brand);font-size:11px;font-weight:700;display:grid;
place-items:center;margin-top:2px}
.intent{display:block;font-size:10.5px;color:var(--muted);margin-top:2px}
.chk{margin:9px 0 0;padding:0;list-style:none;display:flex;flex-direction:column;gap:6px}
.chk li{font-size:12.5px;color:var(--ink-2);display:flex;gap:8px;align-items:flex-start}
.chk li:before{content:"";width:14px;height:14px;border:1.5px solid #c6d0d9;border-radius:4px;
flex:0 0 14px;margin-top:3px}
.pit{margin-top:10px;font-size:12px;color:var(--danger);background:#fdf4f3;
border-left:3px solid #e0b7b2;padding:8px 11px;border-radius:0 8px 8px 0}
.case{margin-top:9px;font-size:12px;color:#8a6a2f;background:#fbf6ec;padding:8px 11px;
border-radius:8px}
.composer{border-top:1px solid var(--line);padding:12px 16px 16px}
.modes{display:flex;gap:7px;margin-bottom:10px;flex-wrap:wrap}
.mode{border:1px solid var(--line);background:#fff;color:var(--ink-2);border-radius:9px;
padding:6px 12px;font-size:12.5px;cursor:pointer;transition:.15s}
.mode:hover{border-color:var(--brand-2);color:var(--brand)}
.mode.on{background:var(--brand);border-color:var(--brand);color:#fff;font-weight:600}
.hintl{font-size:12px;color:var(--muted);align-self:center;margin-right:2px}
.inputrow{display:flex;gap:10px;align-items:flex-end}
textarea{flex:1;resize:none;height:58px;border:1px solid var(--line);border-radius:10px;
padding:10px 12px;font:inherit;font-size:13.5px;outline:none;background:#fbfcfd}
textarea:focus{border-color:var(--brand-2);background:#fff}
.btn{border:0;border-radius:10px;background:var(--brand);color:#fff;padding:11px 20px;
font-size:13.5px;font-weight:600;cursor:pointer;white-space:nowrap}
.btn:hover{background:var(--brand-2)}
.btn.ghost{background:#fff;color:var(--brand);border:1px solid var(--brand)}
.btn.ghost:hover{background:var(--brand-3)}
.attach{width:40px;height:40px;border-radius:10px;border:1px solid var(--line);background:#fff;
display:grid;place-items:center;cursor:pointer;font-size:16px;color:var(--ink-2)}
.attach:hover{border-color:var(--brand-2);color:var(--brand)}
.hintline{font-size:11px;color:var(--muted);margin-top:8px}
.side{display:flex;flex-direction:column;gap:16px}
.panel{padding:16px 18px}
.panel h3{margin:0 0 14px;font-size:12.5px;letter-spacing:1.2px;color:var(--ink-2);
font-weight:600}
.kv{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}
.kv div{background:#f7f9fa;border-radius:9px;padding:9px 11px}
.kv b{display:block;font-size:19px;color:var(--brand);font-weight:600;line-height:1.2}
.kv span{font-size:11px;color:var(--muted)}
.meter{margin-bottom:10px}
.meter .row{display:flex;justify-content:space-between;font-size:12px;margin-bottom:5px}
.meter .row span:last-child{color:var(--brand);font-weight:600}
.track{height:6px;background:#eef1f4;border-radius:4px;overflow:hidden}
.fill{height:100%;border-radius:4px;background:linear-gradient(90deg,#2c8078,#7fc4ba)}
.steps{display:flex;flex-direction:column;gap:2px;margin-bottom:12px}
.step{display:flex;align-items:center;gap:10px;padding:7px 0}
.dot{width:20px;height:20px;border-radius:50%;border:1.5px solid #cfd7de;background:#fff;
display:grid;place-items:center;font-size:10px;color:var(--muted);flex:0 0 20px}
.step.done .dot{background:var(--brand);border-color:var(--brand);color:#fff}
.step.now .dot{background:#fff;border-color:var(--brand);color:var(--brand);font-weight:700;
box-shadow:0 0 0 3px var(--brand-3)}
.step span{font-size:12.5px;color:var(--muted)}
.step.done span{color:var(--ink-2)}
.step.now span{color:var(--brand);font-weight:600}
.line-v{width:1.5px;height:8px;background:#e3e8ed;margin-left:10px}
.constraint{display:flex;gap:6px;flex-wrap:wrap;margin-top:4px}
.chip{font-size:11px;border-radius:20px;padding:3px 9px;background:#eef1f4;color:var(--muted)}
.chip.ok{background:var(--brand-3);color:var(--brand);font-weight:600}
.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:18px}
.kpi{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:16px 18px}
.kpi b{font-size:26px;color:var(--brand);font-weight:600}
.kpi p{margin:2px 0 0;font-size:12px;color:var(--muted)}
.cols{display:grid;grid-template-columns:1.1fr 1fr;gap:18px;margin-bottom:18px}
.bars{display:flex;flex-direction:column;gap:10px}
.bar-row{display:grid;grid-template-columns:74px 1fr 34px;gap:10px;align-items:center;
font-size:12.5px}
.bar{height:9px;background:#eef1f4;border-radius:5px;overflow:hidden}
.bar i{display:block;height:100%;background:linear-gradient(90deg,#2c8078,#8ec9c1);
border-radius:5px}
.bar-row.warn i{background:linear-gradient(90deg,#a8483f,#d79b93)}
.bar-row em{font-style:normal;color:var(--muted);text-align:right;font-size:11.5px}
table{width:100%;border-collapse:collapse;font-size:12.5px}
th,td{padding:10px 8px;text-align:left;border-bottom:1px solid #f0f3f6}
th{font-size:11px;color:var(--muted);font-weight:600;letter-spacing:.6px}
td.name{font-weight:600}
td.name .sub{display:block;font-weight:400;font-size:10.5px;color:var(--muted)}
.mini{display:flex;gap:3px}
.mini i{width:22px;height:5px;border-radius:3px;background:#e8edf1}
.mini i.on{background:var(--brand-2)}
.mini i.mid{background:#c9a06a}
.mini i.low{background:#c98076}
.stagepill{font-size:11px;padding:3px 9px;border-radius:20px;background:#f0f3f6;
color:var(--ink-2)}
.stagepill.active{background:var(--brand-3);color:var(--brand);font-weight:600}
.note{font-size:11.5px;color:var(--muted);margin-top:10px}
.foot{text-align:center;font-size:11.5px;color:#9aa5b1;padding:18px 0 8px}
.headright{display:flex;align-items:center;gap:8px}
.modelsel{border:1px solid var(--line);background:#fff;color:var(--ink-2);border-radius:8px;
padding:4px 6px;font-size:12px;max-width:160px;cursor:pointer;outline:none}
.modelsel:hover{border-color:var(--brand-2)}
.themebtn{border:1px solid var(--line);background:#fff;color:var(--ink-2);border-radius:8px;
padding:4px 10px;font-size:12px;cursor:pointer;transition:.15s}
.themebtn:hover{border-color:var(--brand-2);color:var(--brand)}
.acts{display:flex;gap:4px;margin-top:10px;border-top:1px dashed var(--line);padding-top:8px;
flex-wrap:wrap;position:relative}
.acts button{width:28px;height:28px;padding:0;display:inline-flex;align-items:center;
justify-content:center;border:1px solid transparent;background:transparent;color:var(--muted);
border-radius:8px;font-size:11.5px;cursor:pointer;transition:.15s}
.acts button:hover{background:var(--brand-3);color:var(--brand)}
.acts button.ok{background:#eaf5ec;color:#3f7a52}
.acts svg{width:15px;height:15px;stroke:currentColor;fill:none;stroke-width:1.7;
stroke-linecap:round;stroke-linejoin:round}
.fmtmenu{position:fixed;z-index:70;min-width:104px;background:#fff;border:1px solid var(--line);
border-radius:11px;padding:4px;box-shadow:0 14px 34px rgba(16,35,32,.16)}
.fmtmenu button{width:100%;height:30px;padding:0 8px;justify-content:flex-start;gap:6px;
border:0;background:transparent;border-radius:7px;font-size:12px;color:var(--ink-2)}
.fmtmenu button:hover{background:var(--brand-3);color:var(--brand)}
.fmtmenu .ext{margin-left:auto;color:var(--muted);font-size:11px}
.toast{position:fixed;left:50%;bottom:26px;transform:translateX(-50%) translateY(12px);
background:#1f6f63;color:#fff;padding:8px 18px;border-radius:9px;font-size:13px;
opacity:0;pointer-events:none;transition:.2s;z-index:60;box-shadow:0 4px 14px rgba(0,0,0,.18)}
.toast.show{opacity:1;transform:translateX(-50%) translateY(0)}
.panel h3 .newchat{float:right;border:1px solid var(--line);background:#fff;color:var(--brand);
border-radius:7px;padding:2px 9px;font-size:11px;cursor:pointer;margin-top:-4px;font-weight:500}
.panel h3 .newchat:hover{background:var(--brand-3)}
.sessionlist{display:flex;flex-direction:column;gap:6px;max-height:220px;overflow-y:auto}
.sitem{padding:7px 9px;border:1px solid var(--line);border-radius:8px;cursor:pointer;
background:#fff;transition:.15s}
.sitem:hover{border-color:var(--brand-2)}
.sitem.on{background:var(--brand-3);border-color:var(--brand)}
.sitem .stitle{font-size:12.5px;color:var(--ink);white-space:nowrap;overflow:hidden;
text-overflow:ellipsis}
.sitem .smeta{font-size:10.5px;color:var(--muted);margin-top:1px}
.sempty{font-size:11.5px;color:var(--muted);line-height:1.6}
body.dark{--ink:#e6edf3;--ink-2:#b9c6d1;--muted:#8fa0ae;--line:#2b3a44;--bg:#0f171c;
--card:#162128;--brand:#2f9a8d;--brand-2:#4bb3a5;--brand-3:#1b3330;--danger:#e07a6f}
body.dark .bubble{background:#1b2830;color:var(--ink)}
body.dark .msg.me .bubble{background:var(--brand);color:#fff}
body.dark .msg.me .av{background:#22303a;color:var(--ink-2)}
body.dark .gate{background:rgba(3,8,10,.62)}
body.dark .gate .box{background:#162128}
body.dark .gate input{background:#0f1a20;color:var(--ink);border-color:var(--line)}
body.dark .mode,body.dark .themebtn,body.dark .modelsel,
body.dark .sitem,body.dark .panel h3 .newchat{background:#162128;color:var(--ink-2)}
body.dark .acts button{background:transparent;color:#84959f}
body.dark .acts button:hover{background:#1b3330;color:#7fc4ba}
body.dark .fmtmenu{background:#162128;border-color:#2b3a44}
body.dark .fmtmenu button:hover{background:#1b3330;color:#7fc4ba}
body.dark .sitem.on{background:var(--brand-3)}
body.dark .mode.on,body.dark .msg.me .bubble{background:var(--brand);color:#fff}
body.dark textarea{background:#0f1a20;color:var(--ink);border-color:var(--line)}
body.dark textarea:focus{background:#12202a}
body.dark .attach{background:#162128;color:var(--ink-2);border-color:var(--line)}
body.dark .quiz{background:#1a2229;border-color:#3a2e2e}
body.dark .qtxt{color:var(--ink)}
body.dark .qtitle{color:#d09b9b}
body.dark .opt{background:#162128;color:var(--ink);border-color:#3a2e2e}
body.dark .opt:hover{background:#1d2a32}
body.dark .opt b{color:#e0a1a8}
body.dark .opt.right{background:#1b3326;border-color:#4f8a63}
body.dark .opt.wrong{background:#3a2121;border-color:#9b5b57}
body.dark .qres{color:var(--ink-2)}
body.dark .ansBtn{background:#162128;color:#e0a1a8;border-color:#9b5b57}
body.dark .pit{background:#3a2222;color:#f0b0a8;border-left-color:#8a4f4a}
body.dark .case{background:#2e2618;color:#e0c48a}
body.dark .tag.off{background:#332a18;color:#e0c48a}
body.dark .stagepill{background:#1d2a32}
body.dark .qlist li.click:hover{background:#1d2a32}
body.dark .acts button.ok{background:#1b3326;color:#9fd3ac;border-color:#4f8a63}
body.dark .foot{color:#7b8a96}
@media (max-width:1080px){
.grid{grid-template-columns:1fr}.chat{height:auto;min-height:520px}
.cols{grid-template-columns:1fr}.kpis{grid-template-columns:repeat(2,1fr)}}

/* ============ 视觉优化：更柔和的层次与更舒适的阅读节奏 ============ */
:root{--ink:#1b2430;--ink-2:#46545f;--muted:#7d8b97;--line:#e6eaef;--bg:#f5f7f9;
--card:#fff;--brand:#17615a;--brand-2:#2b847a;--brand-3:#e7f3f0;--danger:#b4534a;
--radius:18px;--shadow:0 1px 2px rgba(16,35,32,.04),0 10px 30px rgba(16,35,32,.06);
--shadow-hover:0 2px 6px rgba(16,35,32,.06),0 16px 40px rgba(16,35,32,.10)}
body{background:
  radial-gradient(1100px 520px at 88% -8%,#e6f1ee 0%,rgba(230,241,238,0) 62%),
  radial-gradient(760px 460px at 2% -4%,#edf3f6 0%,rgba(237,243,246,0) 58%),
  var(--bg);background-attachment:fixed}
.top{background:linear-gradient(112deg,#0e3a37 0%,#16584f 46%,#2a7b6f 100%);
box-shadow:0 10px 34px rgba(12,52,47,.20);position:relative;overflow:hidden}
.top:after{content:"";position:absolute;inset:0;pointer-events:none;
background:radial-gradient(900px 240px at 12% 130%,rgba(255,255,255,.12),transparent 62%)}
.top .inner{height:76px;position:relative;z-index:1}
.logo{background:linear-gradient(145deg,rgba(255,255,255,.22),rgba(255,255,255,.07));
box-shadow:inset 0 1px 0 rgba(255,255,255,.35),0 5px 14px rgba(0,0,0,.14)}
.brand h1{font-size:18px;letter-spacing:.6px}
.brand p{letter-spacing:1.6px}
.nav{padding:4px;border:1px solid rgba(255,255,255,.16)}
.nav a{transition:.18s}
.nav a:hover{background:rgba(255,255,255,.10);color:#fff}
.card,.kpi{box-shadow:var(--shadow);transition:box-shadow .22s,transform .22s}
.card:hover,.kpi:hover{box-shadow:var(--shadow-hover)}
.page{padding:26px 0 46px}
.chat-head{padding:16px 22px;background:linear-gradient(180deg,#fff,#fbfcfd)}
.chat-head h2{font-size:16px;letter-spacing:.2px}
.stream{padding:22px;gap:18px}
.stream::-webkit-scrollbar{width:8px}
.stream::-webkit-scrollbar-thumb{background:#d4dde4;border-radius:8px}
.stream::-webkit-scrollbar-track{background:transparent}
.bubble{background:#fff;border:1px solid #e8edf1;border-radius:16px 16px 16px 7px;
padding:13px 16px;line-height:1.75;box-shadow:0 1px 2px rgba(20,40,36,.04)}
.msg.me .bubble{border-radius:16px 16px 7px 16px;box-shadow:0 6px 18px rgba(23,97,90,.22)}
.msg .av{box-shadow:inset 0 1px 0 rgba(255,255,255,.4)}
.thinking{color:var(--muted);font-size:13px;letter-spacing:1.5px;animation:blink 1.2s ease-in-out infinite}
@keyframes blink{0%,100%{opacity:.45}50%{opacity:1}}
.gate{background:rgba(12,40,37,.55);backdrop-filter:blur(6px)}
.gate .box{border-radius:22px;padding:34px 36px;border:1px solid rgba(255,255,255,.55);
box-shadow:0 30px 80px rgba(9,34,31,.35)}
.gate h2{font-size:21px;letter-spacing:.3px}
.gate p{font-size:13px;line-height:1.75}
.gate input{border-radius:12px;padding:13px 15px;background:#fbfcfd;transition:.18s}
.gate input:focus{border-color:var(--brand-2);background:#fff;
box-shadow:0 0 0 4px rgba(43,132,122,.12)}
.btn{border-radius:12px;padding:12px 22px;box-shadow:0 6px 16px rgba(23,97,90,.20);
transition:transform .16s,box-shadow .16s,background .16s}
.btn:hover{transform:translateY(-1px);box-shadow:0 10px 24px rgba(23,97,90,.26)}
.btn:active{transform:translateY(0)}
.mode{border-radius:10px;padding:7px 13px}
.mode.on{box-shadow:0 4px 12px rgba(23,97,90,.24)}
.composer{padding:14px 18px 18px;background:linear-gradient(180deg,#fbfcfd,#fff)}
textarea{border-radius:14px;padding:12px 14px;height:62px;background:#fff;transition:.18s}
textarea:focus{border-color:var(--brand-2);box-shadow:0 0 0 4px rgba(43,132,122,.10)}
.attach{border-radius:12px;height:42px;width:42px}
.tag{padding:4px 11px}
.panel h3{display:flex;align-items:center;gap:8px}
.panel h3:before{content:"";width:4px;height:14px;border-radius:2px;flex:0 0 4px;
background:linear-gradient(180deg,#2b847a,#7fc4ba)}
.panel h3 .newchat{float:none;margin-left:auto}
.kv div{background:linear-gradient(180deg,#f7fafb,#f1f5f7);border-radius:12px}
.sitem{border-radius:10px;padding:9px 11px}
.sitem.on{box-shadow:0 4px 14px rgba(23,97,90,.12)}
.modelsel,.themebtn{border-radius:9px;padding:5px 9px}
.acts button{border-radius:9px}
.acts{margin-top:12px;padding-top:9px}
.toast{border-radius:12px;background:#14554f;box-shadow:0 10px 30px rgba(9,38,34,.30)}
.brand{min-width:0}
.brand h1{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.nav{flex:0 0 auto}
.nav a{white-space:nowrap}
.tag,.themebtn,.modelsel,.mode{white-space:nowrap}
.headright{flex:0 0 auto}
.msg.me .bubble{max-width:100%}

body.dark{--bg:#0d1519;--card:#151f25;--line:#26333c;--ink:#e7eff5;--ink-2:#b6c4d0;
--muted:#84959f;--brand-3:#16302c;--shadow:0 1px 2px rgba(0,0,0,.20),0 10px 30px rgba(0,0,0,.28);
--shadow-hover:0 2px 6px rgba(0,0,0,.26),0 16px 42px rgba(0,0,0,.34)}
body.dark{background:
  radial-gradient(900px 480px at 88% -8%,rgba(38,90,82,.30) 0%,rgba(38,90,82,0) 62%),
  radial-gradient(700px 420px at 2% -4%,rgba(40,62,74,.28) 0%,rgba(40,62,74,0) 58%),
  var(--bg);background-attachment:fixed}
body.dark .top{box-shadow:0 10px 34px rgba(0,0,0,.38)}
body.dark .chat-head{background:linear-gradient(180deg,#162128,#121b20)}
body.dark .bubble{background:#1a262d;border-color:#26333c;box-shadow:0 1px 2px rgba(0,0,0,.20)}
body.dark .composer{background:linear-gradient(180deg,#121b20,#162128)}
body.dark .kv div{background:linear-gradient(180deg,#1a262d,#172129)}
body.dark textarea{background:#101a1f}
body.dark .gate .box{border-color:#2b3a44}
body.dark .stream::-webkit-scrollbar-thumb{background:#33434d}

@media (max-width:760px){
  .wrap,.top .inner{padding:0 14px}
  .top .inner{display:grid;grid-template-columns:minmax(0,1fr) auto;
  grid-template-areas:"brand who" "nav nav";row-gap:8px;height:auto;
  padding-top:10px;padding-bottom:10px;align-items:center}
  .brand{grid-area:brand;gap:8px}
  .brand p{display:none}
  .brand h1{font-size:15px}
  .logo{width:34px;height:34px;border-radius:10px;flex:0 0 34px}
  .nav{grid-area:nav;justify-self:start}
  .nav a{padding:6px 10px;font-size:12px}
  .who{grid-area:who;gap:5px}
  .who span:first-child{display:none}
  .who b{max-width:64px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
  .who .switch{padding:4px 8px}
  .chat-head{flex-wrap:wrap;row-gap:9px;padding:13px 15px}
  .chat-head h2{flex:1 1 100%}
  .headright{flex:1 1 100%;justify-content:space-between;gap:8px}
  .tag{margin-left:0}
  .page{padding:16px 0 28px}
  .chat{min-height:480px}
  .stream{padding:16px;gap:14px}
  .msg{max-width:96%}
  .composer{padding:12px 14px 14px}
  .gate .box{padding:26px 22px}
  .who{font-size:12px;gap:6px}
  .modelsel{max-width:140px}
  .kpis{grid-template-columns:repeat(2,1fr);gap:10px}
  .kpi{padding:14px}
}
@media (max-width:430px){
  .brand h1{display:none}
  .nav a{padding:6px 8px;font-size:11.5px}
  .who b{max-width:52px}
}
